import datetime


def days_in_month(year: int, month: int) -> int:
    """Backed by datetime: only years 1..9999 and months 1..12 are valid;
    anything else raises ValueError (so year 0 / negative years are rejected)."""
    first = datetime.date(year, month, 1)
    if month == 12:
        nxt = datetime.date(year + 1, 1, 1)
    else:
        nxt = datetime.date(year, month + 1, 1)
    return (nxt - first).days
